import { ICONS_DATA } from '../components/Icon/icons-data.js';
import type { IconName } from '../components/Icon/types.js';

const escape = (value: string) => value.replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]!);
export function iconMarkup(name: string, options: { size?: number | string; label?: string } = {}): string {
  const key = Object.hasOwn(ICONS_DATA, name) ? name as IconName : 'help-circle';
  const meta = ICONS_DATA[key];
  const requested = String(options.size ?? '1em');
  const size = /^\d+(\.\d+)?(px|em|rem)?$/.test(requested) ? requested : '1em';
  const body = meta.elements?.map(([tag, attrs]) => `<${tag} ${Object.entries(attrs).map(([attr, value]) => `${attr}="${escape(value)}"`).join(' ')}/>`).join('') ?? meta.rawHtml ?? '';
  const a11y = options.label ? `role="img" aria-label="${escape(options.label)}"` : 'aria-hidden="true"';
  return `<svg class="rda-icon" data-icon="${key}" xmlns="http://www.w3.org/2000/svg" viewBox="${meta.viewBox}" width="${size}" height="${size}" fill="${meta.type === 'fill' ? 'currentColor' : 'none'}" stroke="${meta.type === 'stroke' ? 'currentColor' : 'none'}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" focusable="false" ${a11y}>${body}</svg>`;
}

export function registerIcons(): void {
  if (typeof customElements === 'undefined' || customElements.get('rda-icon')) return;
  class RdaIcon extends HTMLElement {
    static observedAttributes = ['name', 'size', 'label'];
    connectedCallback(): void { this.render(); }
    attributeChangedCallback(): void { if (this.isConnected) this.render(); }
    private render(): void {
      this.style.display = 'inline-flex';
      this.style.verticalAlign = 'middle';
      this.style.flexShrink = '0';
      this.style.lineHeight = '0';
      this.innerHTML = iconMarkup(this.getAttribute('name') || '', {
        size: this.getAttribute('size') || '1em', label: this.getAttribute('label') || undefined
      });
    }
  }
  customElements.define('rda-icon', RdaIcon);
}
registerIcons();
